return {
  apply(ctx) {
    const fs = ctx.get('fs')
    const sandboxPolicy = ctx.get('sandboxPolicy')
    if (fs === undefined || sandboxPolicy === undefined) return

    const FILE_NAME = '.dsh-bookmarks.json'

    async function loadBookmarks() {
      try {
        const target = await fs.resolve(FILE_NAME, { cwd: sandboxPolicy.workspaceRoot })
        const info = await fs.stat(target)
        if (!info) return []
        const text = await fs.readText(target)
        const data = JSON.parse(text)
        if (Array.isArray(data)) return data
        if (data && Array.isArray(data.bookmarks)) return data.bookmarks
        return []
      } catch (err) {
        console.error('bookmarks: load failed', err)
        return []
      }
    }

    async function saveBookmarks(bookmarks) {
      const target = await fs.resolve(FILE_NAME, { cwd: sandboxPolicy.workspaceRoot })
      const policy = sandboxPolicy.resolve()
      await fs.writeText(target, JSON.stringify({ bookmarks }, null, 2), undefined, undefined, policy)
    }

    harness.handle('bookmarks.list', async () => {
      const bookmarks = await loadBookmarks()
      return { bookmarks }
    })

    harness.handle('bookmarks.save', async (args) => {
      const list = args && Array.isArray(args.bookmarks) ? args.bookmarks : []
      await saveBookmarks(list)
      return { ok: true }
    })
  },
}

