return {
  apply(ctx) {
    const slots = ctx.get('slots')
    if (slots === undefined) return

    styles.insert(`
      .dsw-bm-root { height: 100%; overflow-y: auto; padding: 16px 20px 40px; box-sizing: border-box; color: var(--dsw-alias-label-primary); background: var(--dsw-alias-bg-base); font-size: 14px; line-height: 1.5; }
      .dsw-bm-header { display: flex; align-items: baseline; gap: 10px; margin-bottom: 12px; }
      .dsw-bm-title-lg { font-size: 18px; font-weight: 600; }
      .dsw-bm-count { font-size: 12px; color: var(--dsw-alias-label-secondary); }
      .dsw-bm-add { display: flex; flex-direction: column; gap: 8px; margin-bottom: 10px; padding: 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); }
      .dsw-bm-add-row { display: flex; gap: 8px; }
      .dsw-bm-input { flex: 1; min-width: 0; padding: 7px 10px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-base); color: var(--dsw-alias-label-primary); font-size: 13px; box-sizing: border-box; }
      .dsw-bm-input:focus { outline: none; border-color: var(--dsw-alias-brand-primary); }
      .dsw-bm-search { width: 100%; padding: 7px 10px; margin-bottom: 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font-size: 13px; box-sizing: border-box; }
      .dsw-bm-search:focus { outline: none; border-color: var(--dsw-alias-brand-primary); }
      .dsw-bm-btn { padding: 6px 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 6px; background: var(--dsw-alias-bg-layer-1); color: var(--dsw-alias-label-primary); font-size: 13px; cursor: pointer; white-space: nowrap; }
      .dsw-bm-btn:hover { border-color: var(--dsw-alias-border-l2); }
      .dsw-bm-btn-primary { background: var(--dsw-alias-brand-primary); color: #fff; border-color: transparent; }
      .dsw-bm-btn-danger:hover { border-color: var(--dsw-alias-state-error-primary); color: var(--dsw-alias-state-error-primary); }
      .dsw-bm-error { color: var(--dsw-alias-state-error-primary); font-size: 12px; margin-bottom: 8px; }
      .dsw-bm-list { display: flex; flex-direction: column; gap: 8px; }
      .dsw-bm-card { display: flex; align-items: flex-start; justify-content: space-between; gap: 12px; padding: 10px 12px; border: 1px solid var(--dsw-alias-border-l1); border-radius: 8px; background: var(--dsw-alias-bg-layer-1); }
      .dsw-bm-card-main { min-width: 0; }
      .dsw-bm-title { color: var(--dsw-alias-label-primary); font-weight: 600; text-decoration: none; word-break: break-all; }
      .dsw-bm-title:hover { color: var(--dsw-alias-brand-primary); text-decoration: underline; }
      .dsw-bm-url { color: var(--dsw-alias-label-secondary); font-size: 12px; word-break: break-all; margin-top: 2px; }
      .dsw-bm-note { color: var(--dsw-alias-label-secondary); font-size: 12px; margin-top: 4px; }
      .dsw-bm-card-actions { display: flex; gap: 6px; flex-shrink: 0; }
      .dsw-bm-empty { color: var(--dsw-alias-label-secondary); text-align: center; padding: 32px 0; }
      .dsw-bm-field { display: flex; flex-direction: column; gap: 4px; margin-bottom: 8px; }
      .dsw-bm-label { font-size: 12px; color: var(--dsw-alias-label-secondary); }
      .dsw-bm-actions { display: flex; gap: 6px; justify-content: flex-end; }
    `)

    function BookmarkView() {
      const h = React.createElement
      const [bookmarks, setBookmarks] = React.useState(null)
      const [title, setTitle] = React.useState('')
      const [url, setUrl] = React.useState('')
      const [note, setNote] = React.useState('')
      const [query, setQuery] = React.useState('')
      const [editingId, setEditingId] = React.useState(null)
      const [editTitle, setEditTitle] = React.useState('')
      const [editUrl, setEditUrl] = React.useState('')
      const [editNote, setEditNote] = React.useState('')
      const [error, setError] = React.useState('')

      React.useEffect(() => {
        let alive = true
        host.call('bookmarks.list')
          .then((res) => {
            if (!alive) return
            const list = res && Array.isArray(res.bookmarks) ? res.bookmarks : []
            setBookmarks(list)
          })
          .catch((err) => {
            console.error('bookmarks: load failed', err)
            if (alive) setBookmarks([])
          })
        return () => { alive = false }
      }, [])

      const persist = (next) => {
        setBookmarks(next)
        host.call('bookmarks.save', { bookmarks: next }).catch((err) => {
          console.error('bookmarks: save failed', err)
          setError('保存失败，请重试')
        })
      }

      const normalizeUrl = (u) => {
        let v = u.trim()
        if (!v) return ''
        if (!/^[a-zA-Z][a-zA-Z0-9+.-]*:\/\//.test(v)) v = 'https://' + v
        return v
      }

      const addBookmark = () => {
        const u = normalizeUrl(url)
        if (!u) {
          setError('请输入网址')
          return
        }
        const now = Date.now()
        const item = {
          id: now.toString(36) + Math.random().toString(36).slice(2, 8),
          title: title.trim() || u,
          url: u,
          note: note.trim(),
          createdAt: now,
          updatedAt: now,
        }
        persist([item].concat(bookmarks || []))
        setTitle('')
        setUrl('')
        setNote('')
        setError('')
      }

      const removeBookmark = (id) => {
        persist((bookmarks || []).filter((b) => b.id !== id))
        if (editingId === id) setEditingId(null)
      }

      const startEdit = (b) => {
        setEditingId(b.id)
        setEditTitle(b.title)
        setEditUrl(b.url)
        setEditNote(b.note || '')
      }

      const cancelEdit = () => setEditingId(null)

      const commitEdit = (b) => {
        const u = normalizeUrl(editUrl)
        if (!u) {
          setError('网址不能为空')
          return
        }
        const next = (bookmarks || []).map((x) => x.id === b.id
          ? { id: x.id, title: editTitle.trim() || u, url: u, note: editNote.trim(), createdAt: x.createdAt, updatedAt: Date.now() }
          : x)
        persist(next)
        setEditingId(null)
        setError('')
      }

      const q = query.trim().toLowerCase()
      const filtered = (bookmarks || []).filter((b) => {
        if (!q) return true
        return (b.title || '').toLowerCase().includes(q) ||
               (b.url || '').toLowerCase().includes(q) ||
               (b.note || '').toLowerCase().includes(q)
      })

      const items = filtered.map((b) => {
        if (b.id === editingId) {
          return h('div', { key: b.id, className: 'dsw-bm-card' },
            h('div', { className: 'dsw-bm-card-main' },
              h('div', { className: 'dsw-bm-field' },
                h('label', { className: 'dsw-bm-label' }, '标题'),
                h('input', { className: 'dsw-bm-input', value: editTitle, onChange: (e) => setEditTitle(e.target.value), placeholder: '标题（可选）' }),
              ),
              h('div', { className: 'dsw-bm-field' },
                h('label', { className: 'dsw-bm-label' }, '网址'),
                h('input', { className: 'dsw-bm-input', value: editUrl, onChange: (e) => setEditUrl(e.target.value), placeholder: 'https://…' }),
              ),
              h('div', { className: 'dsw-bm-field' },
                h('label', { className: 'dsw-bm-label' }, '备注'),
                h('input', { className: 'dsw-bm-input', value: editNote, onChange: (e) => setEditNote(e.target.value), placeholder: '备注（可选）' }),
              ),
            ),
            h('div', { className: 'dsw-bm-card-actions' },
              h('button', { className: 'dsw-bm-btn dsw-bm-btn-primary', onClick: () => commitEdit(b) }, '保存'),
              h('button', { className: 'dsw-bm-btn', onClick: cancelEdit }, '取消'),
            ),
          )
        }
        return h('div', { key: b.id, className: 'dsw-bm-card' },
          h('div', { className: 'dsw-bm-card-main' },
            h('a', { className: 'dsw-bm-title', href: b.url, target: '_blank', rel: 'noreferrer' }, b.title),
            h('div', { className: 'dsw-bm-url' }, b.url),
            b.note ? h('div', { className: 'dsw-bm-note' }, b.note) : null,
          ),
          h('div', { className: 'dsw-bm-card-actions' },
            h('button', { className: 'dsw-bm-btn', onClick: () => startEdit(b) }, '编辑'),
            h('button', { className: 'dsw-bm-btn dsw-bm-btn-danger', onClick: () => removeBookmark(b.id) }, '删除'),
          ),
        )
      })

      const enterAdd = (e) => { if (e.key === 'Enter') addBookmark() }

      return h('div', { className: 'dsw-bm-root' },
        h('div', { className: 'dsw-bm-header' },
          h('div', { className: 'dsw-bm-title-lg' }, '书签'),
          bookmarks ? h('div', { className: 'dsw-bm-count' }, '共 ' + bookmarks.length + ' 条') : null,
        ),
        h('div', { className: 'dsw-bm-add' },
          h('input', { className: 'dsw-bm-input', value: url, onChange: (e) => setUrl(e.target.value), onKeyDown: enterAdd, placeholder: '网址，如 example.com（必填）' }),
          h('div', { className: 'dsw-bm-add-row' },
            h('input', { className: 'dsw-bm-input', value: title, onChange: (e) => setTitle(e.target.value), onKeyDown: enterAdd, placeholder: '标题（可选）' }),
            h('input', { className: 'dsw-bm-input', value: note, onChange: (e) => setNote(e.target.value), onKeyDown: enterAdd, placeholder: '备注（可选）' }),
            h('button', { className: 'dsw-bm-btn dsw-bm-btn-primary', onClick: addBookmark }, '添加'),
          ),
        ),
        error ? h('div', { className: 'dsw-bm-error' }, error) : null,
        h('input', { className: 'dsw-bm-search', value: query, onChange: (e) => setQuery(e.target.value), placeholder: '搜索书签…' }),
        bookmarks === null
          ? h('div', { className: 'dsw-bm-empty' }, '加载中…')
          : items.length
            ? h('div', { className: 'dsw-bm-list' }, items)
            : h('div', { className: 'dsw-bm-empty' }, q ? '没有匹配的书签' : '还没有书签，在上方添加第一条吧'),
      )
    }

    slots.inject('conversation.view', () => slots.register(
      { name: 'conversation.view', id: 'bookmarks', order: 20, label: '书签' },
      () => React.createElement(BookmarkView, null),
    ))
  },
}
